<?php require_once __DIR__ . '/../conexion.php';$r=$conexion->query("SELECT nocontrol_prof,nombre_prof,apaterno_prof,amaterno_prof,mail_prof,tel_prof,estatus_prof FROM profesores ORDER BY nombre_prof");?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lista de profesores</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/estilos.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><a href="../index.php" class="btn btn-secondary mb-3 d-print-none">Volver al menú</a><h2>Lista de profesores</h2><div class="table-responsive"><table class="table table-bordered table-striped"><thead class="table-dark"><tr><th>No. control</th><th>Nombre</th><th>Correo</th><th>Teléfono</th><th>Estatus</th></tr></thead><tbody><?php while($f=$r->fetch_assoc()):?><tr><td><?php echo htmlspecialchars($f['nocontrol_prof']);?></td><td><?php echo htmlspecialchars($f['nombre_prof'].' '.$f['apaterno_prof'].' '.$f['amaterno_prof']);?></td><td><?php echo htmlspecialchars($f['mail_prof']);?></td><td><?php echo htmlspecialchars($f['tel_prof']);?></td><td><?php echo htmlspecialchars($f['estatus_prof']);?></td></tr><?php endwhile;?></tbody></table></div><button onclick="print()" class="btn btn-primary d-print-none">Imprimir</button></main></body></html>
